CREATE TABLE IF NOT EXISTS admin_sessions(token_hash TEXT PRIMARY KEY,google_sub TEXT NOT NULL,email TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_exp ON admin_sessions(expires_at);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',sku TEXT NOT NULL DEFAULT '',price_cents INTEGER,image_url TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,customer_name TEXT NOT NULL DEFAULT '',contact TEXT NOT NULL DEFAULT '',service TEXT NOT NULL DEFAULT '',starts_at TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new',notes TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enquiries(id TEXT PRIMARY KEY,customer_name TEXT NOT NULL DEFAULT '',contact TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advertisements(id TEXT PRIMARY KEY,title TEXT NOT NULL DEFAULT '',caption TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',scheduled_at TEXT NOT NULL DEFAULT '',product_id TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
